<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\MaintenanceRecord;use App\Models\Payment;use App\Models\VehicleReturn;use Carbon\Carbon;use Illuminate\Http\Request;use Inertia\Inertia;
class FinancialReportController extends Controller{public function index(Request $request){$data=$request->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$from=isset($data['from'])?Carbon::parse($data['from'])->startOfDay():now()->startOfMonth();$to=isset($data['to'])?Carbon::parse($data['to'])->endOfDay():now()->endOfDay();$payments=Payment::query()->with('booking.customer')->whereIn('status',['PAID','SUCCEEDED'])->whereBetween('paid_at',[$from,$to]);$returns=VehicleReturn::query()->whereBetween('return_datetime',[$from,$to]);$expenses=MaintenanceRecord::query()->with(['vehicle','type'])->whereBetween('maintenance_date',[$from->toDateString(),$to->toDateString()]);$income=(clone $payments)->sum('amount');$additional=(clone $returns)->sum('total_additional_charge');$expenseTotal=(clone $expenses)->sum('cost');return Inertia::render('Admin/Reports/Financial',['filters'=>['from'=>$from->toDateString(),'to'=>$to->toDateString()],'summary'=>['payment_total'=>$income,'payment_count'=>(clone $payments)->count(),'late_fee'=>(clone $returns)->sum('late_fee'),'damage_fee'=>(clone $returns)->sum('damage_fee'),'fuel_fee'=>(clone $returns)->sum('fuel_fee'),'cleaning_fee'=>(clone $returns)->sum('cleaning_fee'),'additional_total'=>$additional,'maintenance_total'=>$expenseTotal,'net_total'=>$income-$expenseTotal],'payments'=>$payments->latest('paid_at')->paginate(20)->withQueryString(),'expenses'=>$expenses->latest('maintenance_date')->take(10)->get()]);}}
